
import React, { useState, ChangeEvent } from "react";
import "./ImageUpload.scss"; // Import the CSS file
import { MpaIcon } from "../icon/MpaIcon";
import { SvgMpaIcon } from "../../assets/icons";
import CircularLoader from "../loader/CircularLoader";
import LinearLoader from "../loader/LinearLoader";

export interface ImageUploadProps {
  /**
   * Identifying value for the chip.
   */
  id: string;
  /**
   * Text value to be displayed next to the chip.
   */
  label: string;
  /**
   * Determines the colour palette of the file upload.
   */

  colour?: "primary" | "secondary" | "tertiary";
  /**
   * Text value to be displayed for image upload.
   */
  uploadMessage: string;
  /**
     * Text value to be displayed for warning.
     */
  warningMessage: string;
  /**
     * Number of images.
     */
  imageNumber: number;
  /**
     * Each image size in MB.
     */
  imageSize: number;
  /**
   * Determines if the button can be interacted with.
  */
  inProgress?: boolean;
  /**
  * Determines the progress of the loader.
  */
  progress?: number;
  /**
   * Determines the style of the preview.
   */

  style?: "list" | "grid";
  /**
   * Callback function to handle file changes.
   */
  onFilesChange?: (files: UploadedImage[]) => void;
}
interface UploadedImage {
  file: File;
  preview: string;
}
const ImageUpload: React.FC<ImageUploadProps> = ({
  id,
  label = "Image Upload",
  colour = "primary",
  uploadMessage = "Tap to Upload",
  warningMessage = "Maximum file size: 5MB and 3 images only.",
  imageNumber = 3,
  imageSize = 5,
  inProgress = false,
  progress = 0,
  style = "list",
  onFilesChange
}) => {
  const [images, setImages] = useState<UploadedImage[]>([]);
  const [errors, setErrors] = useState<{ name: string; reason: string }[]>([]);

  const handleImageChange = (e: ChangeEvent<HTMLInputElement>) => {
    const files = e.target.files;
    if (!files) return;

    const allowedTypes = ['image/jpeg', 'image/png', 'image/webp'];
    const fileArray = Array.from(files);

    // Check file limits
    if (fileArray.length + images.length > imageNumber) {
      setErrors([{ name: 'Upload Limit', reason: `You can only upload up to ${imageNumber} images.` }]);
      return;
    }

    const validImages: File[] = [];
    const newErrors: { name: string; reason: string }[] = [];

    fileArray.forEach(file => {
      if (!allowedTypes.includes(file.type)) {
        newErrors.push({ name: file.name, reason: 'Invalid file type' });
      } else if (file.size > imageSize * 1024 * 1024) {
        newErrors.push({ name: file.name, reason: 'File size exceeds 5MB' });
      } else {
        validImages.push(file);
      }
    });

    const newImages: UploadedImage[] = validImages.map(file => ({
      file,
      preview: URL.createObjectURL(file),
    }));

    setImages(prev => [...prev, ...newImages]);
    setErrors(prev => [...prev, ...newErrors]);
    onFilesChange?.([...images, ...newImages]);
  };

  const handleRemoveImage = (indexToRemove: number) => {
    setImages((prevImages) =>
      prevImages.filter((_, index) => index !== indexToRemove)
    );
    onFilesChange?.(images.filter((_, index) => index !== indexToRemove));
  };
  const handleRemoveImageError = (indexToRemove: number) => {
    setErrors((prevImages) =>
      prevImages.filter((_, index) => index !== indexToRemove)
    );
  };
  const loaderColour = `var(--mpa-fileupload-${colour}-color)`;
  return (
    <div>

      <div className="upload-wrapper">
        <span className="upload-title">{label}</span>
        <span className="upload-warning">
          {warningMessage}
        </span>

        <label className={`upload-box ${colour}-box`}>
          <input
            type="file"
            multiple
            accept="image/*"
            onChange={handleImageChange}
            hidden
          />

          <div className={`upload-icon ${colour}-imageUpload`}>
            {<MpaIcon iconName="CloudUpload" size={32} />}
          </div>
          <p className={`upload-text ${colour}-imageUpload`}>{uploadMessage}</p>
        </label>
        {style == "grid" ?
          <div className="preview-container">
            {images.map((img, index) => (
              <div key={index} className="preview-wrapper">
                <img
                  key={index}
                  src={img.preview}
                  alt={`upload-${index}`}
                  className="preview-image"
                />

                {
                  inProgress ?
                  <div>
                    <div className="overlay"></div>
                    <div className="checkmark-circle">
                      <CircularLoader id={'1'} size={'small'}></CircularLoader>
                    </div>
                  </div> :
                    <div className="checkmark-circle checkmark-circle-sucess">
                      {<MpaIcon iconName="Check" size={16} colour={'white'} />}

                    </div>
                }

                <button
                  className="remove-button"
                  onClick={() => handleRemoveImage(index)}
                >
                  {SvgMpaIcon.X({ size: 16, color: "white" })}

                </button>

                <div className="image-labels">
                  <div className="file-title">Image Upload</div>
                  <div className="file-meta">
                    <span>{img.file.type.split("/")[1].toUpperCase()}</span>
                    <span>{(img.file.size / (1024 * 1024)).toFixed(1)}MB</span>
                  </div>
                </div>
              </div>
            ))}
            {errors.map((error, index) => (
              <div>
                <div key={index} className="upload-error-card">


                  <div className="warning-icon">!</div>
                  <button
                    className="remove-button"
                    onClick={() => handleRemoveImageError(index)}
                  >
                    {SvgMpaIcon.X({ size: 16, color: "white" })}

                  </button>
                </div>
                <div className="image-labels">
                  <div className="file-title">{error.name}</div>
                  <div className="file-meta-red">
                    <span>{error.reason}</span>
                    <span></span>
                  </div>
                </div>
              </div>
            ))}
          </div> :
          <div className="preview-list">
            {images.map((img, index) => (
              (
                <div key={index} className={`upload-card adjust-margin`}>
                  <div className="upload-info">
                    <div className="file-icon">
                      {<MpaIcon iconName="FilePdf_SGDS" size={24} colour="#565A5C" />}
                    </div>
                    <div className="file-details img-file-details">
                      <div className="file-name img-file-name">{img.file.name}</div>
                      <div className="file-meta">
                        {(img.file.size / (1024 * 1024)).toFixed(2)}MB &nbsp; &bull; &nbsp;  {progress > 0 ? (
                          <span>Uploading: {progress}%</span>
                        ) : (
                          <span>Upload Completed</span>
                        )}
                      </div>
                    </div>
                    <div className="delete-icon" onClick={() => handleRemoveImage(index)}>
                      {<MpaIcon iconName="Trash" size={20} />}
                    </div>
                  </div>
                  <div className="progress-bar-file">
                    {progress > 0 ? <LinearLoader id={"linear_loader_2"} colour={loaderColour} progress={progress} showProgress={false} bar_width="100%"></LinearLoader> :
                      <LinearLoader id={"linear_loader_3"} colour="var(--mpa-green)" progress={100} showProgress={false} bar_width="100%"></LinearLoader>}


                  </div>
                </div>
              )
            ))}
            {errors.map((error, index) => (
              (
                <div>
                  <div className="upload-card adjust-margin">
                    <div className="upload-info">
                      <div className="file-icon error-bg error-file-colour">
                        {<MpaIcon iconName="FilePdf_SGDS" />}
                      </div>
                      <div className="file-details">
                        <div className="file-name error">{error.name}</div>
                        <div className="file-meta error">
                          {(200 / (1024 * 1024)).toFixed(2)}MB &nbsp; &bull; &nbsp; Upload Failed
                        </div>
                      </div>
                      <div className="delete-icon" onClick={() => handleRemoveImageError(index)}>
                        {<MpaIcon iconName="Trash" size={20} />}
                      </div>
                    </div>
                    <div className="progress-bar-file">

                      <LinearLoader id={"linear_loader_1"} colour="var(--mpa-red)" progress={25} showProgress={false} bar_width="100%"></LinearLoader>
                    </div>

                  </div>
                  <div className="label-icon-container label-adjust">
                    <span className="help-icon error">
                      {<MpaIcon iconName="AlertCircle" size={18} />}
                    </span>
                    <span className="label-text error">{error.reason}</span>
                  </div>
                </div>
              )
            ))}
          </div>
        }
      </div>


    </div>
  );
};

export default ImageUpload;